eleteAction":"c","updateAction":"a"}],"memberships":[],"dependencies":[{"kind":"n","function":"auth.jwt()","referenced":"schema auth","referencedClass":"pg_namespace"},{"kind":"n","function":"auth.uid()","referenced":"schema auth","referencedClass":"pg_namespace"},{"kind":"n","function":"b1i2_entity_identity()","referenced":"language plpgsql","referencedClass":"pg_language"},{"kind":"n","function":"b1i2_entity_identity()","referenced":"schema public","referencedClass":"pg_namespace"},{"kind":"n","function":"b1i2_protect_closed_truncate()","referenced":"language plpgsql","referencedClass":"pg_language"},{"kind":"n","function":"b1i2_protect_closed_truncate()","referenced":"schema public","referencedClass":"pg_namespace"},{"kind":"n","function":"b1i2_state_identity()","referenced":"language plpgsql","referencedClass":"pg_language"},{"kind":"n","function":"b1i2_state_identity()","referenced":"schema public","referencedClass":"pg_namespace"},{"kind":"n","function":"check_user_app_state_immutability()","referenced":"language plpgsql","referencedClass":"pg_language"},{"kind":"n","function":"check_user_app_state_immutability()","referenced":"schema public","referencedClass":"pg_namespace"},{"kind":"n","function":"close_annual_snapshot_atomic(uuid,integer,jsonb,jsonb)","referenced":"language plpgsql","referencedClass":"pg_language"},{"kind":"n","function":"close_annual_snapshot_atomic(uuid,integer,jsonb,jsonb)","referenced":"schema public","referencedClass":"pg_namespace"},{"kind":"n","function":"get_my_role()","referenced":"schema public","referencedClass":"pg_namespace"},{"kind":"n","function":"is_admin()","referenced":"schema public","referencedClass":"pg_namespace"}]}$verified_catalog$::jsonb;
BEGIN
 -- Deliberately fail closed outside the qualified synthetic model. Hosted catalog needs a separate authorized addendum.
 IF current_database() <> 'b1_synthetic' THEN RAISE EXCEPTION 'B1_COMPLETION_HOSTED_CATALOG_NOT_QUALIFIED'; END IF;
 observed := (WITH
fn AS (
 SELECT p.*, n.nspname, l.lanname FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace JOIN pg_language l ON l.oid=p.prolang
 WHERE p.oid=ANY(ARRAY['public.is_admin()'::regprocedure,'public.get_my_role()'::regprocedure,
 'public.check_user_app_state_immutability()'::regprocedure,'public.b1i2_state_identity()'::regprocedure,
 'public.b1i2_entity_identity()'::regprocedure,'public.b1i2_protect_closed_truncate()'::regprocedure,
 'public.close_annual_snapshot_atomic(uuid,integer,jsonb,jsonb)'::regprocedure,'auth.uid()'::regprocedure,'auth.jwt()'::regprocedure])
),
rels AS (SELECT c.* FROM pg_class c WHERE c.oid=ANY(ARRAY['public.entities'::regclass,'public.user_app_state'::regclass,'public.profiles'::regclass,'auth.users'::regclass])),
acl_functions AS (
 SELECT p.oid,COALESCE(jsonb_agg(jsonb_build_object('grantor',pg_get_userbyid(a.grantor),'grantee',CASE WHEN a.grantee=0 THEN 'PUBLIC' ELSE pg_get_userbyid(a.grantee) END,'privilege',a.privilege_type,'grantable',a.is_grantable) ORDER BY a.grantee::regrole::text,a.privilege_type),'[]'::jsonb) acl
 FROM fn p LEFT JOIN LATERAL aclexplode(COALESCE(p.proacl,acldefault('f',p.proowner))) a ON true GROUP BY p.oid
)
SELECT jsonb_build_object(
'functions',(SELECT jsonb_agg(jsonb_build_object('schema',p.nspname,'name',p.proname,'args',pg_get_function_identity_arguments(p.oid),'result',pg_get_function_result(p.oid),'owner',pg_get_userbyid(p.proowner),'definer',p.prosecdef,'config',COALESCE(to_jsonb(p.proconfig),'[]'::jsonb),'bodyMD5',md5(replace(p.prosrc,chr(13),'')),'language',p.lanname,'volatility',p.provolatile,'strict',p.proisstrict,'acl',a.acl) ORDER BY p.nspname,p.proname,pg_get_function_identity_arguments(p.oid)) FROM fn p JOIN acl_functions a USING(oid)),
'triggers',(SELECT COALESCE(jsonb_agg(jsonb_build_object('relation',t.tgrelid::regclass::text,'name',t.tgname,'function',t.tgfoid::regprocedure::text,'type',t.tgtype,'enabled',t.tgenabled,'definition',pg_get_triggerdef(t.oid,true)) ORDER BY t.tgrelid::regclass::text,t.tgname),'[]'::jsonb) FROM pg_trigger t WHERE t.tgrelid IN('public.entities'::regclass,'public.user_app_state'::regclass) AND NOT t.tgisinternal),
'relations',(SELECT jsonb_agg(jsonb_build_object('name',r.oid::regclass::text,'owner',pg_get_userbyid(r.relowner),'rls',r.relrowsecurity,'forceRLS',r.relforcerowsecurity,'acl',(SELECT jsonb_agg(jsonb_build_object('grantee',CASE WHEN a.grantee=0 THEN 'PUBLIC' ELSE pg_get_userbyid(a.grantee) END,'grantor',pg_get_userbyid(a.grantor),'privilege',a.privilege_type,'grantable',a.is_grantable) ORDER BY a.grantee::regrole::text,a.privilege_type) FROM aclexplode(COALESCE(r.relacl,acldefault('r',r.relowner))) a)) ORDER BY r.oid::regclass::text) FROM rels r),
'columns',(SELECT jsonb_agg(jsonb_build_object('relation',a.attrelid::regclass::text,'name',a.attname,'position',a.attnum,'type',format_type(a.atttypid,a.atttypmod),'notNull',a.attnotnull,'generated',a.attgenerated,'identity',a.attidentity,'default',pg_get_expr(d.adbin,d.adrelid),'acl',a.attacl::text) ORDER BY a.attrelid::regclass::text,a.attnum) FROM pg_attribute a LEFT JOIN pg_attrdef d ON d.adrelid=a.attrelid AND d.adnum=a.attnum WHERE a.attrelid IN(SELECT oid FROM rels) AND a.attnum>0 AND NOT a.attisdropped),
'constraints',(SELECT jsonb_agg(jsonb_build_object('relation',c.conrelid::regclass::text,'name',c.conname,'type',c.contype,'definition',pg_get_constraintdef(c.oid,true),'validated',c.convalidated,'deferrable',c.condeferrable,'deferred',c.condeferred,'updateAction',c.confupdtype,'deleteAction',c.confdeltype,'referenced',CASE WHEN c.confrelid=0 THEN NULL ELSE c.confrelid::regclass::text END) ORDER BY c.conrelid::regclass::text,c.conname) FROM pg_constraint c WHERE c.conrelid IN(SELECT oid FROM rels)),
'policies',(SELECT jsonb_agg(to_jsonb(x) ORDER BY x.schemaname,x.tablename,x.policyname) FROM pg_policies x WHERE (x.schemaname='public' AND x.tablename IN('entities','user_app_state','profiles'))),
'roles',(SELECT jsonb_agg(jsonb_build_object('name',rolname,'super',rolsuper,'inherit',rolinherit,'createRole',rolcreaterole,'createDB',rolcreatedb,'login',rolcanlogin,'replication',rolreplication,'bypassRLS',rolbypassrls) ORDER BY rolname) FROM pg_roles WHERE rolname IN('postgres','anon','authenticated','service_role')),
'memberships',(SELECT COALESCE(jsonb_agg(jsonb_build_object('role',pg_get_userbyid(m.roleid),'member',pg_get_userbyid(m.member),'admin',m.admin_option,'inherit',m.inherit_option,'set',m.set_option) ORDER BY pg_get_userbyid(m.roleid),pg_get_userbyid(m.member)),'[]'::jsonb) FROM pg_auth_members m WHERE m.roleid IN(SELECT oid FROM pg_roles WHERE rolname IN('postgres','anon','authenticated','service_role')) OR m.member IN(SELECT oid FROM pg_roles WHERE rolname IN('postgres','anon','authenticated','service_role'))),
'schemas',(SELECT jsonb_agg(jsonb_build_object('name',n.nspname,'owner',pg_get_userbyid(n.nspowner),'acl',(SELECT jsonb_agg(jsonb_build_object('grantor',pg_get_userbyid(a.grantor),'grantee',CASE WHEN a.grantee=0 THEN 'PUBLIC' ELSE pg_get_userbyid(a.grantee) END,'privilege',a.privilege_type,'grantable',a.is_grantable) ORDER BY a.grantee::regrole::text,a.privilege_type) FROM aclexplode(COALESCE(n.nspacl,acldefault('n',n.nspowner))) a)) ORDER BY n.nspname) FROM pg_namespace n WHERE n.nspname IN('public','auth')),
'dependencies',(SELECT COALESCE(jsonb_agg(jsonb_build_object('function',d.objid::regprocedure::text,'kind',d.deptype,'referencedClass',d.refclassid::regclass::text,'referenced',pg_describe_object(d.refclassid,d.refobjid,d.refobjsubid)) ORDER BY d.objid::regprocedure::text,d.deptype,pg_describe_object(d.refclassid,d.refobjid,d.refobjsubid)),'[]'::jsonb) FROM pg_depend d WHERE d.classid='pg_proc'::regclass AND d.objid IN(SELECT oid FROM fn))
));
 IF observed IS DISTINCT FROM expected THEN RAISE EXCEPTION 'B1_COMPLETION_CATALOG_PRE_MISMATCH'; END IF;
END $complete_pre$;
ALTER TABLE public.user_app_state ADD COLUMN b1i4_version uuid NOT NULL DEFAULT gen_random_uuid();
ALTER TABLE public.user_app_state ADD COLUMN b1i4_expected uuid;
CREATE SCHEMA b1i5_private AUTHORIZATION postgres;
REVOKE ALL ON SCHEMA b1i5_private FROM PUBLIC,anon,authenticated,service_role;
CREATE TABLE b1i5_private.permits(tx bigint,pid integer,entity uuid,year integer,op text,expected uuid,PRIMARY KEY(tx,pid,entity,year,op));
ALTER TABLE b1i5_private.permits OWNER TO postgres;
REVOKE ALL ON b1i5_private.permits FROM PUBLIC,anon,authenticated,service_role;
CREATE FUNCTION public.b1i5_version_guard() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public,pg_temp AS $$
DECLARE permitted uuid; required uuid; e uuid; y integer; historical boolean;
BEGIN
 e:=CASE WHEN TG_OP='DELETE' THEN OLD.entity_id ELSE NEW.entity_id END;
 y:=CASE WHEN TG_OP='DELETE' THEN OLD.current_year ELSE NEW.current_year END;
 DELETE FROM b1i5_private.permits WHERE tx=txid_current() AND pid=pg_backend_pid() AND entity=e AND year=y AND op=TG_OP AND rel=TG_RELID RETURNING expected INTO permitted;
 IF TG_OP='DELETE' THEN
  IF OLD.fund_data#>>'{metadata,snapshotStatus}' IS DISTINCT FROM 'OPEN' THEN RAISE EXCEPTION USING ERRCODE='P0001',MESSAGE='STATE_NOT_OPEN'; END IF;
  IF permitted IS DISTINCT FROM OLD.b1i4_version THEN RAISE EXCEPTION USING ERRCODE='P0001',MESSAGE='STATE_VERSION_CONFLICT'; END IF;
  RETURN OLD;
 END IF;
 IF TG_OP='INSERT' THEN
  IF NEW.fund_data#>>'{metadata,snapshotStatus}' IS DISTINCT FROM 'OPEN' THEN RAISE EXCEPTION USING ERRCODE='P0001',MESSAGE='STATE_NOT_OPEN'; END IF;
  required:='00000000-0000-0000-0000-000000000000'::uuid;
 ELSE
  required:=OLD.b1i4_version;
  historical:=(OLD.fund_data#>>'{metadata,snapshotStatus}') IS DISTINCT FROM 'OPEN';
  IF historical AND (NEW.fund_data->'metadata') IS DISTINCT FROM (OLD.fund_data->'metadata') THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='HISTORICAL_METADATA_IMMUTABLE'; END IF;
  IF NOT historical AND (NEW.fund_data#>>'{metadata,snapshotStatus}') IS DISTINCT FROM 'OPEN' AND ((NEW.fund_data#>>'{metadata,snapshotStatus}') IS DISTINCT FROM 'CLOSED' OR permitted IS DISTINCT FROM required) THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='VERSIONED_CLOSURE_REQUIRED'; END IF;
 END IF;
 IF COALESCE(NEW.b1i4_expected,permitted) IS DISTINCT FROM required THEN RAISE EXCEPTION USING ERRCODE='P0001',MESSAGE='STATE_VERSION_CONFLICT'; END IF;
 NEW.b1i4_version:=gen_random_uuid(); NEW.b1i4_expected:=NULL; RETURN NEW;
END $$;
ALTER FUNCTION public.b1i5_version_guard() OWNER TO postgres;
REVOKE ALL ON FUNCTION public.b1i5_version_guard() FROM PUBLIC,anon,authenticated,service_role;
CREATE TRIGGER zz_b1i5_version BEFORE INSERT OR UPDATE OR DELETE ON public.user_app_state FOR EACH ROW EXECUTE FUNCTION public.b1i5_version_guard();
CREATE FUNCTION public.close_annual_snapshot_versioned(p_entity_id uuid,p_current_year integer,p_current_version uuid,p_next_version uuid,p_closed_fund_data jsonb,p_next_fund_data jsonb) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public,pg_temp AS $$
DECLARE cur public.user_app_state%ROWTYPE; nxt public.user_app_state%ROWTYPE; owner_id uuid; result jsonb; next_exists boolean;
BEGIN
 IF auth.uid() IS NULL THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='STATE_PERMISSION_DENIED'; END IF;
 SELECT user_id INTO owner_id FROM public.entities WHERE id=p_entity_id FOR SHARE;
 IF owner_id IS NULL OR (owner_id<>auth.uid() AND public.is_admin() IS DISTINCT FROM true) THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='STATE_PERMISSION_DENIED'; END IF;
 -- Serialize two versioned closures. Direct concurrent writers are still caught by row tokens.
 PERFORM pg_advisory_xact_lock(hashtextextended(p_entity_id::text,0));
 SELECT * INTO cur FROM public.user_app_state WHERE entity_id=p_entity_id AND current_year=p_current_year FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE='P0002',MESSAGE='STATE_NOT_FOUND'; END IF;
 IF cur.fund_data#>>'{metadata,snapshotStatus}' IS DISTINCT FROM 'OPEN' THEN RAISE EXCEPTION USING ERRCODE='P0001',MESSAGE='STATE_NOT_OPEN'; END IF;
 IF p_current_version IS NULL OR p_current_version IS DISTINCT FROM cur.b1i4_version THEN RAISE EXCEPTION USING ERRCODE='P0001',MESSAGE='STATE_VERSION_CONFLICT'; END IF;
 SELECT * INTO nxt FROM public.user_app_state WHERE entity_id=p_entity_id AND current_year=p_current_year+1 FOR UPDATE;
 next_exists:=FOUND;
 IF next_exists AND nxt.fund_data#>>'{metadata,snapshotStatus}' IS DISTINCT FROM 'OPEN' AND nxt.fund_data#>>'{metadata,snapshotStatus}' IS DISTINCT FROM 'CLOSED' THEN RAISE EXCEPTION USING ERRCODE='P0001',MESSAGE='STATE_NOT_OPEN'; END IF;
 IF (next_exists AND p_next_version IS DISTINCT FROM nxt.b1i4_version) OR (NOT next_exists AND p_next_version IS NOT NULL) THEN RAISE EXCEPTION USING ERRCODE='P0001',MESSAGE='STATE_VERSION_CONFLICT'; END IF;
 INSERT INTO b1i5_private.permits VALUES(txid_current(),pg_backend_pid(),p_entity_id,p_current_year,'UPDATE',cur.b1i4_version);
 INSERT INTO b1i5_private.permits VALUES(txid_current(),pg_backend_pid(),p_entity_id,p_current_year+1,CASE WHEN next_exists THEN 'UPDATE' ELSE 'INSERT' END,CASE WHEN next_exists THEN nxt.b1i4_version ELSE '00000000-0000-0000-0000-000000000000'::uuid END);
 -- Exact existing f911 economic implementation; no economic expressions copied or changed.
 result:=public.close_annual_snapshot_atomic(p_entity_id,p_current_year,p_closed_fund_data,p_next_fund_data);
 DELETE FROM b1i5_private.permits WHERE tx=txid_current() AND pid=pg_backend_pid() AND entity=p_entity_id AND year IN(p_current_year,p_current_year+1);
 RETURN result||jsonb_build_object('currentVersion',(SELECT b1i4_version FROM public.user_app_state WHERE entity_id=p_entity_id AND current_year=p_current_year),'nextVersion',(SELECT b1i4_version FROM public.user_app_state WHERE entity_id=p_entity_id AND current_year=p_current_year+1),'currentSnapshot',(SELECT to_jsonb(s) FROM public.user_app_state s WHERE entity_id=p_entity_id AND current_year=p_current_year),'nextSnapshot',(SELECT to_jsonb(s) FROM public.user_app_state s WHERE entity_id=p_entity_id AND current_year=p_current_year+1));
END $$;
ALTER FUNCTION public.close_annual_snapshot_versioned(uuid,integer,uuid,uuid,jsonb,jsonb) OWNER TO postgres;
REVOKE ALL ON FUNCTION public.close_annual_snapshot_versioned(uuid,integer,uuid,uuid,jsonb,jsonb) FROM PUBLIC,anon,authenticated,service_role;
GRANT EXECUTE ON FUNCTION public.close_annual_snapshot_versioned(uuid,integer,uuid,uuid,jsonb,jsonb) TO authenticated;
ALTER TABLE b1i5_private.permits ADD COLUMN rel oid NOT NULL DEFAULT 'public.user_app_state'::regclass CHECK(rel='public.user_app_state'::regclass);
CREATE FUNCTION public.b1i6_no_truncate() RETURNS trigger LANGUAGE plpgsql SET search_path=pg_catalog AS $$ BEGIN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='UNVERSIONED_TRUNCATE_DENIED'; END $$;
ALTER FUNCTION public.b1i6_no_truncate() OWNER TO postgres;
REVOKE ALL ON FUNCTION public.b1i6_no_truncate() FROM PUBLIC,anon,authenticated,service_role;
CREATE TRIGGER zz_b1i6_no_truncate BEFORE TRUNCATE ON public.user_app_state FOR EACH STATEMENT EXECUTE FUNCTION public.b1i6_no_truncate();
CREATE FUNCTION public.delete_annual_snapshot_versioned(p_entity_id uuid,p_year integer,p_version uuid) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public,pg_temp AS $$
DECLARE owner_id uuid; s public.user_app_state%ROWTYPE; deleted_count bigint;
BEGIN
 IF auth.uid() IS NULL THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='STATE_PERMISSION_DENIED'; END IF;
 SELECT user_id INTO owner_id FROM public.entities WHERE id=p_entity_id FOR SHARE;
 IF owner_id IS NULL OR (owner_id<>auth.uid() AND public.is_admin() IS DISTINCT FROM true) THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='STATE_PERMISSION_DENIED'; END IF;
 SELECT * INTO s FROM public.user_app_state WHERE entity_id=p_entity_id AND current_year=p_year FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE='P0002',MESSAGE='STATE_NOT_FOUND'; END IF;
 IF s.fund_data#>>'{metadata,snapshotStatus}' IS DISTINCT FROM 'OPEN' THEN RAISE EXCEPTION USING ERRCODE='P0001',MESSAGE='STATE_NOT_OPEN'; END IF;
 IF p_version IS NULL OR p_version IS DISTINCT FROM s.b1i4_version THEN RAISE EXCEPTION USING ERRCODE='P0001',MESSAGE='STATE_VERSION_CONFLICT'; END IF;
 INSERT INTO b1i5_private.permits(tx,pid,entity,year,op,expected) VALUES(txid_current(),pg_backend_pid(),p_entity_id,p_year,'DELETE',s.b1i4_version);
 DELETE FROM public.user_app_state WHERE entity_id=p_entity_id AND current_year=p_year;
 GET DIAGNOSTICS deleted_count = ROW_COUNT;
 IF deleted_count <> 1 OR EXISTS(SELECT 1 FROM b1i5_private.permits WHERE tx=txid_current() AND pid=pg_backend_pid() AND entity=p_entity_id AND year=p_year) THEN RAISE EXCEPTION USING ERRCODE='P0001',MESSAGE='DELETE_SCOPE_MISMATCH'; END IF;
 RETURN jsonb_build_object('success',true,'deleted',1);
END $$;
CREATE FUNCTION public.delete_entity_versioned(p_entity_id uuid,p_versions jsonb) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public,pg_temp AS $$
DECLARE owner_id uuid; s public.user_app_state%ROWTYPE; deleted_count bigint; expected jsonb;
BEGIN
 IF auth.uid() IS NULL THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='STATE_PERMISSION_DENIED'; END IF;
 SELECT user_id INTO owner_id FROM public.entities WHERE id=p_entity_id FOR UPDATE;
 IF owner_id IS NULL OR (owner_id<>auth.uid() AND public.is_admin() IS DISTINCT FROM true) THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='STATE_PERMISSION_DENIED'; END IF;
 FOR s IN SELECT * FROM public.user_app_state WHERE entity_id=p_entity_id ORDER BY current_year FOR UPDATE LOOP
  IF s.fund_data#>>'{metadata,snapshotStatus}' IS DISTINCT FROM 'OPEN' THEN RAISE EXCEPTION USING ERRCODE='P0001',MESSAGE='STATE_NOT_OPEN'; END IF;
 END LOOP;
 SELECT COALESCE(jsonb_object_agg(current_year::text,b1i4_version::text),'{}'::jsonb) INTO expected FROM public.user_app_state WHERE entity_id=p_entity_id;
 IF p_versions IS NULL OR p_versions IS DISTINCT FROM expected THEN RAISE EXCEPTION USING ERRCODE='P0001',MESSAGE='STATE_VERSION_CONFLICT'; END IF;
 INSERT INTO b1i5_private.permits(tx,pid,entity,year,op,expected) SELECT txid_current(),pg_backend_pid(),entity_id,current_year,'DELETE',b1i4_version FROM public.user_app_state WHERE entity_id=p_entity_id;
 DELETE FROM public.entities WHERE id=p_entity_id;
 GET DIAGNOSTICS deleted_count = ROW_COUNT;
 IF deleted_count <> 1 THEN RAISE EXCEPTION USING ERRCODE='P0001',MESSAGE='DELETE_SCOPE_MISMATCH'; END IF;
 IF EXISTS(SELECT 1 FROM b1i5_private.permits WHERE tx=txid_current() AND pid=pg_backend_pid() AND entity=p_entity_id) THEN RAISE EXCEPTION USING ERRCODE='P0001',MESSAGE='DELETE_SCOPE_MISMATCH'; END IF;
 RETURN jsonb_build_object('success',true,'deleted',1);
END $$;
ALTER FUNCTION public.delete_annual_snapshot_versioned(uuid,integer,uuid) OWNER TO postgres;
ALTER FUNCTION public.delete_entity_versioned(uuid,jsonb) OWNER TO postgres;
REVOKE ALL ON FUNCTION public.delete_annual_snapshot_versioned(uuid,integer,uuid),public.delete_entity_versioned(uuid,jsonb) FROM PUBLIC,anon,authenticated,service_role;
GRANT EXECUTE ON FUNCTION public.delete_annual_snapshot_versioned(uuid,integer,uuid),public.delete_entity_versioned(uuid,jsonb) TO authenticated;
COMMIT;
